import categoryModel from"../models/categoryModel.js";const buildTree=(categories,parentId=null)=>categories.filter((cat=>String(cat.parentId)===String(parentId))).sort(((a,b)=>a.order-b.order)).map((cat=>({...cat._doc,children:buildTree(categories,cat._id)}))),addCategory=async(req,res)=>{try{const{name:name,slug:slug,parentId:parentId=null,isCampaign:isCampaign,showInNavbar:showInNavbar,active:active,order:order}=req.body;if(!name||!slug)return res.status(400).json({success:!1,message:"Name y slug son obligatorios"});if(await categoryModel.findOne({slug:slug}))return res.status(400).json({success:!1,message:"El slug ya existe"});const newCategory=new categoryModel({name:name,slug:slug,parentId:parentId,isCampaign:isCampaign||!1,showInNavbar:showInNavbar??!0,active:active??!0,order:order||0});await newCategory.save(),res.json({success:!0,data:newCategory})}catch(error){res.status(500).json({success:!1,message:error.message})}},listCategories=async(req,res)=>{try{const categories=await categoryModel.find({active:!0}).sort({order:1});res.json({success:!0,categories:categories})}catch(error){res.status(500).json({success:!1,message:error.message})}},listCategoriesTree=async(req,res)=>{try{const categories=await categoryModel.find({active:!0}),tree=buildTree(categories);res.json({success:!0,categories:tree})}catch(error){res.status(500).json({success:!1,message:error.message})}},singleCategory=async(req,res)=>{try{const{categoryId:categoryId}=req.body,category=await categoryModel.findById(categoryId);if(!category)return res.status(404).json({success:!1,message:"Categoría no encontrada"});res.json({success:!0,category:category})}catch(error){res.status(500).json({success:!1,message:error.message})}},updateCategory=async(req,res)=>{try{const{id:id}=req.params,{name:name,slug:slug,parentId:parentId,isCampaign:isCampaign,showInNavbar:showInNavbar,active:active,order:order}=req.body;if(!id)return res.status(400).json({success:!1,message:"ID requerido"});if(id===parentId)return res.status(400).json({success:!1,message:"Una categoría no puede ser su propio padre"});if(slug){const existing=await categoryModel.findOne({slug:slug});if(existing&&existing._id.toString()!==id)return res.status(400).json({success:!1,message:"El slug ya existe"})}const updated=await categoryModel.findByIdAndUpdate(id,{name:name,slug:slug,parentId:parentId,isCampaign:isCampaign,showInNavbar:showInNavbar,active:active,order:order},{new:!0});res.json({success:!0,data:updated})}catch(error){res.status(500).json({success:!1,message:error.message})}},deleteWithChildren=async id=>{const children=await categoryModel.find({parentId:id});for(const child of children)await deleteWithChildren(child._id);await categoryModel.findByIdAndDelete(id)},removeCategory=async(req,res)=>{try{const{id:id}=req.params;if(!id)return res.status(400).json({success:!1,message:"ID requerido"});await deleteWithChildren(id),res.json({success:!0})}catch(error){res.status(500).json({success:!1,message:error.message})}},getBreadcrumbs=async(req,res)=>{try{const{categoryId:categoryId}=req.params;let breadcrumbs=[],current=await categoryModel.findById(categoryId);for(;current;)breadcrumbs.unshift(current),current=current.parentId?await categoryModel.findById(current.parentId):null;res.json({success:!0,breadcrumbs:breadcrumbs})}catch(error){res.status(500).json({success:!1,message:error.message})}};export{addCategory,listCategories,listCategoriesTree,singleCategory,updateCategory,removeCategory,getBreadcrumbs};